#!/usr/bin/env julia
# Chiquipoli: one entry point for a reader of the package.
#
#     julia --project=. chiquipoli.jl              what is certified, read from the records (seconds)
#     julia --project=. chiquipoli.jl help         every task
#
# This file only presents. It reads results/ and runs the scripts of pipeline/,
# test/ and lean/ unchanged; it is not part of the certified code, and it never
# writes a record (every certifier runs with CHIQUI_NO_RECORD=1). The records are
# regenerated by `make check-all`.

using TOML, Printf, SHA, Dates

const ROOT = @__DIR__
const COLOR = isempty(get(ENV, "NO_COLOR", "")) && stdout isa Base.TTY
const SCOPE = (16, 32, 64)            # the polygons of the article

# ── styling ─────────────────────────────────────────────────────────────────
const CODES = Dict(:bold => "1", :dim => "2", :red => "31", :green => "32",
                   :yellow => "33", :blue => "34", :magenta => "35", :cyan => "36")
sty(s, ks::Symbol...) = COLOR && !isempty(ks) ?
    "\e[" * join((CODES[k] for k in ks), ";") * "m" * string(s) * "\e[0m" : string(s)
plain(s) = replace(string(s), r"\e\[[0-9;]*m" => "")
width(s) = textwidth(plain(s))
pad(s, w; right = false) = (n = max(w - width(s), 0); right ? " "^n * s : s * " "^n)

function verdict(s)
    t = uppercase(plain(s))
    occursin(r"FAIL|STALE|MISMATCH|NOT ", t) ? sty(s, :red, :bold) :
    occursin(r"CERTIFIED|PROVEN|PASS|^YES|^OK", t) ? sty(s, :green, :bold) :
    occursin(r"SKIP|ABSENT|—", t) ? sty(s, :dim) : sty(s, :yellow)
end

const BANNER = [
    " ██████╗██╗  ██╗██╗ ██████╗ ██╗   ██╗██╗██████╗  ██████╗ ██╗     ██╗",
    "██╔════╝██║  ██║██║██╔═══██╗██║   ██║██║██╔══██╗██╔═══██╗██║     ██║",
    "██║     ███████║██║██║   ██║██║   ██║██║██████╔╝██║   ██║██║     ██║",
    "██║     ██╔══██║██║██║▄▄ ██║██║   ██║██║██╔═══╝ ██║   ██║██║     ██║",
    "╚██████╗██║  ██║██║╚██████╔╝╚██████╔╝██║██║     ╚██████╔╝███████╗██║",
    " ╚═════╝╚═╝  ╚═╝╚═╝ ╚══▀▀═╝  ╚═════╝ ╚═╝╚═╝      ╚═════╝ ╚══════╝╚═╝",
]
function banner()
    println()
    foreach(l -> println("  ", sty(l, :cyan, :bold)), BANNER)
    println()
    println("  ", sty("exact, interval and formal verification of equilateral small polygons", :dim))
    println("  ", sty("strict local maximality of the Bingane–Audet polygons A₁₆, A₃₂, A₆₄", :dim))
end

const RULE = 86
rulew() = min(RULE, clamp(something(tryparse(Int, get(ENV, "COLUMNS", "")), displaysize(stdout)[2]), 60, 140) - 2)
section(t) = (println(); println(sty("═"^rulew(), :blue)); println("  ", sty(t, :bold));
              println(sty("═"^rulew(), :blue)))
note(s) = println("  ", sty(s, :dim))

# A box-drawn table. `right` lists the columns aligned to the right. Column
# `wrap` (the last by default; give the prose column, never a file name) is
# wrapped between words to fit the terminal, never cut; rows that wrap are
# separated by a rule.
termcols() = clamp(something(tryparse(Int, get(ENV, "COLUMNS", "")), displaysize(stdout)[2]), 60, 140)

function wrapcell(s, w)
    out = String[]; cur = ""
    for word in split(plain(s), ' ')
        while width(word) > w
            isempty(cur) || (push!(out, cur); cur = "")
            push!(out, first(word, w)); word = chop(word; head = length(first(word, w)), tail = 0)
        end
        if isempty(cur)
            cur = String(word)
        elseif width(cur) + 1 + width(word) <= w
            cur *= " " * word
        else
            push!(out, cur); cur = String(word)
        end
    end
    push!(out, cur)
    return out
end

function table(header, rows; right = Int[], wrap = length(header))
    isempty(rows) && return note("(nothing to show)")
    n = length(header); c = wrap
    w = [maximum(width(r[j]) for r in vcat([header], rows)) for j in 1:n]
    room = termcols() - (2 + 3n + 1) - (sum(w) - w[c])
    w[c] = clamp(w[c], 0, max(room, 16))
    line(l, m, r) = println("  ", sty(l * join(("─"^(x + 2) for x in w), m) * r, :dim))
    function row(cells; bold = false)
        last = width(cells[c]) > w[c] ? wrapcell(cells[c], w[c]) : [string(cells[c])]
        for (k, piece) in enumerate(last)
            cs = [j == c ? piece : k == 1 ? cells[j] : "" for j in 1:n]
            println("  ", sty("│", :dim),
                join((" " * pad(bold ? sty(c, :bold) : c, w[j]; right = j in right) * " "
                      for (j, c) in enumerate(cs)), sty("│", :dim)), sty("│", :dim))
        end
        return length(last) > 1
    end
    wraps = any(r -> width(r[c]) > w[c], rows)
    line("┌", "┬", "┐"); row(header; bold = true); line("├", "┼", "┤")
    for (i, r) in enumerate(rows)
        row(r)
        wraps && i < length(rows) && line("├", "┼", "┤")
    end
    line("└", "┴", "┘")
end

# ── reading the records ─────────────────────────────────────────────────────
rec(path) = (p = joinpath(ROOT, path); isfile(p) ? TOML.parsefile(p) : nothing)
big(s) = parse(BigFloat, string(s))
# A bound is printed rounded in the direction that keeps it true: a lower bound
# (≥) down, an upper bound (≤) up. Rounding to nearest could print a lower bound
# above the certified one, which is a false statement.
function sig(x; d = 4, dir = :nearest)
    x = BigFloat(x)
    iszero(x) && return "0"
    e = floor(Int, log10(abs(x)))
    sc = BigFloat(10)^(d - 1 - e)
    v = dir === :down ? floor(x * sc) / sc : dir === :up ? ceil(x * sc) / sc : round(x * sc) / sc
    abs(v) < 1e-3 ? @sprintf("%.*e", d - 1, Float64(v)) : @sprintf("%.*g", d, Float64(v))
end
lo(x; d = 4) = sig(x; d = d, dir = :down)
hi(x; d = 4) = sig(x; d = d, dir = :up)
num(x) = x === nothing ? "—" : lo(big(x))
gate(r, id) = r === nothing ? nothing :
    (i = findfirst(g -> get(g, "id", "") == id, get(r, "gate", Any[])); i === nothing ? nothing : r["gate"][i])
detail(g, re) = (g === nothing ? nothing :
    (m = match(re, get(g, "detail", "")); m === nothing ? nothing : m.captures[1]))

# Does the record still describe the tree? Compares every recorded SHA256.
function describes_tree(r)
    r === nothing && return "absent"
    hs = get(r, "source_sha256", Any[])
    isempty(hs) && return "—"
    stale = count(e -> (f = joinpath(ROOT, e["file"]); !isfile(f) || bytes2hex(open(sha256, f)) != e["sha256"]), hs)
    stale == 0 ? "yes ($(length(hs)) files)" : "STALE ($stale of $(length(hs)) files changed)"
end
short(c) = (s = string(c); occursin(r"^[0-9a-f]{40}$", s) ? s[1:7] : "—")
yesno(b) = b === true ? "yes" : b === false ? "NO" : "—"

# ── status ──────────────────────────────────────────────────────────────────
function status()
    a16 = rec("results/a16_certificate.toml")
    rad = rec("results/radius_certificate.toml")
    lean = rec("results/lean_certificate.toml")
    leanf = rec("results/lean_family_certificate.toml")
    val = rec("results/validation_certificate.toml")
    fam = Dict(n => rec("results/family/A$n.toml") for n in SCOPE)
    famz = Dict(n => rec("results/family/Z$n.toml") for n in (32, 64))
    vd(r, key = "certified") = r === nothing ? "absent" :
        (get(r, key, get(get(r, "verdict", Dict()), "certified", false)) === true ? "CERTIFIED" : "NOT CERTIFIED")

    section("WHAT IS CERTIFIED · the results of the article and their records")
    rows = Any[]
    push!(rows, ["Theorem 6.3", "A₁₆ strict local maximiser · Julia", vd(a16), "a16_certificate.toml"])
    push!(rows, ["Theorem 6.3", "the same, kernel-checked · Lean",
                 lean === nothing ? "absent" : (get(lean, "certified", false) ? "PASS" : "FAIL"), "lean_certificate.toml"])
    r = rad === nothing ? nothing : get(rad, "radius", Dict())
    push!(rows, ["Theorem 6.4", r === nothing ? "explicit radius" : "radius r ≥ " * lo(big(r["r_lower_bound"])) * " · Julia",
                 rad === nothing ? "absent" : "CERTIFIED", "radius_certificate.toml"])
    for (n, sub) in ((32, "₃₂"), (64, "₆₄"))
        push!(rows, ["Theorem 6.6", "A$sub strict local maximiser · Julia",
                     fam[n] === nothing ? "absent" : get(fam[n], "verdict", "?"), "family/A$n.toml"])
    end
    push!(rows, ["Thms 6.3, 6.6", "A₁₆, A₃₂, A₆₄ kernel-checked · Lean",
                 leanf === nothing ? "absent" : (get(leanf, "certified", false) ? "PASS" : "FAIL"), "lean_family_certificate.toml"])
    if val !== nothing
        bs = get(val, "benchmark", Any[])
        ok = count(b -> get(b, "expectation_met", false) === true, bs)
        neg = count(b -> get(b, "negative_control", false) === true, bs)
        push!(rows, ["benchmark", "known optima + $neg broken controls",
                     ok == length(bs) ? "PASS $ok/$(length(bs))" : "FAIL $ok/$(length(bs))", "validation_certificate.toml"])
    end
    for (n, sub) in ((32, "₃₂"), (64, "₆₄"))
        push!(rows, ["new", "Z$sub strict local maximiser · Julia",
                     famz[n] === nothing ? "absent" : get(famz[n], "verdict", "?"), "family/Z$n.toml"])
    end
    ind = Dict(nm => rec("results/independent/$nm.toml") for nm in ("A16", "A32", "A64", "Z32", "Z64"))
    nind = count(r -> r !== nothing && startswith(get(r, "status", ""), "CERTIFIED"), values(ind))
    push!(rows, ["new", "A₁₆, A₃₂, A₆₄, Z₃₂, Z₆₄ again · Python, independent",
                 nind == 5 ? "CERTIFIED 5/5" : nind == 0 ? "absent" : "NOT CERTIFIED $nind/5", "independent/*.toml"])
    table(["article", "statement · method", "verdict", "record in results/"], [[x[1], x[2], verdict(x[3]), x[4]] for x in rows]; wrap = 2)
    note("Global optimality is not claimed for any polygon.")

    section("A₁₆ · THE HYPOTHESES OF THEOREM 3.5, GATE BY GATE (Proposition 6.2)")
    if a16 === nothing
        note("results/a16_certificate.toml is absent.")
    else
        val_of = Dict(
            "existence"        => g -> "in Z_root, radius " * sig(big(a16["meta"]["z_root_radius"]); d = 2),
            "side_length"      => g -> "16ℓ ∈ [" * string(g["perimeter_lower"])[1:16] * "…]",
            "convexity"        => g -> "min det ≥ " * lo(big(g["min_support_determinant"])),
            "inactive_margin"  => g -> "δ_inact ≥ " * lo(big(g["inactive_margin_lower_bound"])),
            "multipliers"      => g -> "min λ ≥ " * lo(big(g["min_lambda_lower_bound"])),
            "rank"             => g -> "‖I − CM‖∞ ≤ " * hi(big(g["preconditioned_regularity_bound"]); d = 3),
            "exact_identities" => g -> "$(g["sides_proved"]) + $(g["diameters_proved"]) identities in ℚ[c]",
            "box_nesting"      => g -> "by endpoints")
        order = [("existence", "Prop 6.2(1)", "unique constructor root"),
                 ("side_length", "Prop 6.2(2)", "side ℓ and perimeter 16ℓ"),
                 ("convexity", "Prop 6.2(3)", "strict convexity, cyclic order"),
                 ("inactive_margin", "Prop 6.2(4)", "exact active graph, inactive margin"),
                 ("multipliers", "Prop 6.2(5)", "positive multipliers, stationarity"),
                 ("rank", "Prop 6.2(6)", "rank 30, so I_eq = R_eq"),
                 ("exact_identities", "Lemma 6.1", "16 sides, 15 diameters, exactly"),
                 ("box_nesting", "§6.3", "Z_root ⊂ int Z_cert")]
        rows = Any[]
        for (id, art, what) in order
            g = gate(a16, id)
            g === nothing && continue
            push!(rows, [art, what, haskey(val_of, id) ? (try val_of[id](g) catch; "—" end) : "—", verdict(string(g["status"]))])
        end
        table(["article", "hypothesis", "certified", "status"], rows; wrap = 2)
        note("Equalities: exact arithmetic in ℚ[c]. Inequalities: outward-rounded intervals, 256 bits.")
    end

    section("THE THREE POLYGONS · Tables 1 and 4 of the article")
    rows = Any[]
    for n in SCOPE
        f = fam[n]
        if n == 16 && a16 !== nothing && f !== nothing
            # Proposition 6.2 prints the dedicated certificate's values (the family
            # certificate of A16 pins the multipliers differently).
            push!(rows, ["A16", @sprintf("%.10f", Float64(big(detail(gate(f, "box_nesting"), r"Z_root = \[([0-9.e+-]+)")))),
                @sprintf("%.10f", Float64(big(gate(a16, "side_length")["perimeter_lower"]))),
                num(gate(a16, "convexity")["min_support_determinant"]),
                num(gate(a16, "inactive_margin")["inactive_margin_lower_bound"]),
                num(gate(a16, "multipliers")["min_lambda_lower_bound"]), verdict(vd(a16))])
            continue
        end
        f === nothing && (push!(rows, ["A$n", "—", "—", "—", "—", "—", "absent"]); continue)
        zl = detail(gate(f, "box_nesting"), r"Z_root = \[([0-9.e+-]+)")
        P = get(something(gate(f, "side_length"), Dict()), "perimeter", nothing)
        push!(rows, ["A$n",
            zl === nothing ? "—" : @sprintf("%.10f", Float64(big(zl))),
            P === nothing ? "—" : @sprintf("%.10f", Float64(big(P))),
            num(detail(gate(f, "convexity"), r"min inf = ([0-9.e+-]+)")),
            num(detail(gate(f, "inactive_margin"), r"margin≥([0-9.e+-]+)")),
            num(detail(gate(f, "multipliers"), r"λ_ij ≥ ([0-9.e+-]+)")),
            verdict(get(f, "verdict", "?"))])
    end
    for n in (32, 64)                       # Z_n: not in the article's theorem, same table
        f = famz[n]
        f === nothing && (push!(rows, ["Z$n", "—", "—", "—", "—", "—", "absent"]); continue)
        zl = detail(gate(f, "box_nesting"), r"Z_root = \[([0-9.e+-]+)")
        P = get(something(gate(f, "side_length"), Dict()), "perimeter", nothing)
        push!(rows, ["Z$n",
            zl === nothing ? "—" : @sprintf("%.10f", Float64(big(zl))),
            P === nothing ? "—" : @sprintf("%.10f", Float64(big(P))),
            num(detail(gate(f, "convexity"), r"min inf = ([0-9.e+-]+)")),
            num(detail(gate(f, "inactive_margin"), r"margin≥([0-9.e+-]+)")),
            num(detail(gate(f, "multipliers"), r"λ_ij ≥ ([0-9.e+-]+)")),
            verdict(get(f, "verdict", "?"))])
    end
    table(["polygon", "root z_n", "perimeter nℓ", "min det ≥", "δ_inact ≥", "min λ ≥", "verdict"], rows; right = 2:6)
    note("Z₃₂, Z₆₄ (Bingane–Audet, larger perimeter): certified like A₃₂, A₆₄; Lean proves their local maximality at every root of the equation in the certified bracket, not the uniqueness of the root.")

    section("THE INDEPENDENT CROSS-CHECK · the same gates, a second implementation")
    rows = Any[]
    for nm in ("A16", "A32", "A64", "Z32", "Z64")
        r = ind[nm]
        if r === nothing; push!(rows, [nm, "—", "—", "—", "—", "—", "absent"]); continue; end
        g = get(r, "geometry", Dict()); l = get(r, "linear_certificate", Dict())
        push!(rows, [nm, first(get(g, "perimeter_enclosure", ["—"])[1], 12),
                     num(get(g, "minimum_support_determinant_lower_bound", nothing)),
                     num(get(g, "inactive_margin_lower_bound", nothing)),
                     num(get(l, "minimum_diameter_multiplier_lower_bound", nothing)),
                     hi(big(get(l, "regularity_norm_upper_bound", "1")); d = 3),
                     verdict(startswith(get(r, "status", ""), "CERTIFIED") ? "CERTIFIED" : "NOT CERTIFIED")])
    end
    table(["polygon", "perimeter ≥", "min det ≥", "δ_inact ≥", "min λ ≥", "‖I − CM‖∞ ≤", "verdict"], rows; right = 2:6)
    note("Python standard library only, integer interval arithmetic; it shares no code with the Julia pipeline.")
    note("A₁₆, A₃₂, A₆₄ agree with the Julia records to every printed digit.")

    section("THE FORMAL LAYER · Lean 4")
    if lean === nothing
        note("results/lean_certificate.toml is absent.")
    else
        th = get(lean, "theorems", Dict()); m = get(lean, "meta", Dict())
        rows = [["headline theorem", string(get(th, "headline", "—"))],
                ["axioms", join(get(th, "axioms", String[]), ", ")],
                ["audited theorems", string(get(th, "axiom_audited_theorems", "—"))],
                ["negative controls rejected", "$(get(th, "negative_controls_rejected", "?")) of $(get(th, "negative_controls_total", "?"))"],
                ["no sorry, no floating point", yesno(get(get(lean, "checks", Dict()), "no_sorry", nothing))],
                ["toolchain", string(get(m, "lean_toolchain", "—"))],
                ["Mathlib", first(string(get(m, "mathlib_rev", "—")), 12)]]
        if leanf !== nothing
            for n in SCOPE
                c = get(get(leanf, "cases", Dict()), "A$n", nothing)
                c === nothing || push!(rows, ["family A$n", string(get(c, "headline", "—"))])
            end
        end
        table(["item", "value"], rows)
    end

    section("PROVENANCE · does each record describe this tree?")
    rows = Any[]
    for (name, r) in [("a16_certificate.toml", a16), ("radius_certificate.toml", rad),
                      ("validation_certificate.toml", val),
                      [("family/A$n.toml", fam[n]) for n in SCOPE]...,
                      [("family/Z$n.toml", famz[n]) for n in (32, 64)]...,
                      ("lean_certificate.toml", lean), ("lean_family_certificate.toml", leanf)]
        m = r === nothing ? Dict() : get(r, "meta", Dict())
        push!(rows, [name, short(get(m, "git_commit", "")), yesno(get(m, "git_source_clean", nothing)),
                     string(get(m, "utc", "—"))[1:min(end, 10)], verdict(describes_tree(r))])
    end
    head = try strip(read(`git -C $ROOT rev-parse --short HEAD`, String)) catch; "—" end
    table(["record (results/)", "commit", "clean tree", "date", "matches the sources"], rows; wrap = 5)
    note("HEAD is $head. A record is evidence while its SHA256 hashes match the tree.")
    note("Full check: julia --project=. chiquipoli.jl records")

    section("REPRODUCE")
    table(["to re-run", "command"], [
        ["the A₁₆ certificate (Theorem 6.3)", "julia --project=. chiquipoli.jl verify"],
        ["the explicit radius (Theorem 6.4)", "julia --project=. chiquipoli.jl radius"],
        ["A₃₂ and A₆₄ (Theorem 6.6)", "julia --project=. chiquipoli.jl family"],
        ["Z₃₂ and Z₆₄ (Theorem 6.8)", "julia --project=. chiquipoli.jl z"],
        ["the test suite", "julia --project=. chiquipoli.jl test"],
        ["the records against the tree", "julia --project=. chiquipoli.jl records"],
        ["the Lean layer (needs lake)", "julia --project=. chiquipoli.jl lean"],
        ["all of the above but Lean", "julia --project=. chiquipoli.jl all"]])
    note("None of these writes a record. To regenerate them: make check-all.")
    return true
end

# ── running the scripts ─────────────────────────────────────────────────────
const RESULTS = Any[]                 # (task, verdict, seconds, log)

# The checks a script reports, one per line as [name]  PASS  detail: its own
# "X PASS = true" lines, the gates of a family certificate (with their detail),
# the exact identities counted once, the test totals, every failure of the
# records check; and the verdict lines the script prints.
# Where in the article each check of the A16 certificate is stated.
const REF = Dict(
    "strict monotonicity on search interval" => "Prop 6.2(1) · 0 ∉ F′(I_search)",
    "domain" => "Prop 6.2(1) · Z_root ⊂ I_search",
    "derivative" => "Prop 6.2(1) · 0 ∉ F′(Z_root)",
    "Newton" => "Prop 6.2(1) · N(Z_root) ⊂ int Z_root",
    "unique root in box" => "Prop 6.2(1)",
    "unique root in whole search interval" => "Prop 6.2(1)",
    "strict convexity" => "Prop 6.2(3) · 224 support determinants > 0",
    "inactive" => "Prop 6.2(4) · 105 inactive pairs at distance < 1",
    "minor regular" => "Prop 6.2(6) · ‖I − CM‖∞ < 1",
    "rank 30" => "Prop 6.2(6) · rank D(e,d) = 30",
    "normalized matrix" => "§6.4 · the normalised system M₀ is regular",
    "Krawczyk" => "Prop 6.2(5) · the multipliers are enclosed",
    "all lambdas positive" => "Prop 6.2(5) · every λ_ij > 0",
    "omitted equations recovered" => "§6.4 · the three omitted equations hold",
    "nominal ell inside its certified enclosure" => "Prop 6.2(2)",
    "root box inside the interior of the boxes of 03, 04, 05" => "§6.3 · Z_root ⊂ int Z_cert")

function condensed(out)
    rows = Any[]; seen = Set{String}(); heads = String[]
    nid = 0; nidok = 0; nok = 0
    add(name, ok, d = "") = (k = lowercase(name); k in seen || (push!(seen, k); push!(rows, (name, ok, isempty(d) ? get(REF, name, "") : d))))
    for l in split(replace(out, r"\e\[[0-9;]*m" => ""), '\n')
        if (m = match(r"^\s*(.+?) PASS = (true|false)\s*$", l)) !== nothing
            add(m.captures[1], m.captures[2] == "true")
        elseif (m = match(r"^([A-Za-z][A-Za-z0-9_]*)\s{2,}(PASS|FAIL)\s+(.*)$", l)) !== nothing
            add(m.captures[1], m.captures[2] == "PASS", m.captures[3])
        elseif occursin(r"^(edge|diam) \(\d+,\d+\):", l)
            nid += 1; occursin("PROVED", l) && (nidok += 1)
        elseif (m = match(r"^Chiquipoli\s+\|\s+(\d+)\s+(\d+)", l)) !== nothing
            add("test suite", m.captures[1] == m.captures[2], "$(m.captures[1]) of $(m.captures[2]) assertions")
        elseif occursin(r"\s+ok$", l)
            nok += 1
        elseif (m = match(r"^\s*(.+?)\s+\*\*\*\s*(.*?)\s*\*\*\*\s*$", l)) !== nothing
            add(m.captures[1], false, m.captures[2])
        elseif occursin(r"^(FINAL FIRST-ORDER CERTIFICATE|FAMILY CERTIFICATE A|EXPLICIT RADIUS|RECORDS CHECK|LEAN CERTIFICATE|INDEPENDENT CROSS-CHECK)", l)
            push!(heads, strip(l))
        end
    end
    if nid > 0
        filter!(r -> lowercase(r[1]) != "exact identities", rows)
        push!(rows, ("exact identities", nidok == nid, "Lemma 6.1 · $nidok of $nid equalities, exact in ℚ[c]"))
    end
    nok > 0 && push!(rows, ("checks reported ok", true, "$nok"))
    return rows, heads
end

function print_checks(rows, heads)
    cols = something(tryparse(Int, get(ENV, "COLUMNS", "")), displaysize(stdout)[2])
    cols = clamp(cols, 60, 140)
    nw = min(maximum((width(r[1]) + 2 for r in rows); init = 0), 44)
    for (n, ok, d) in rows
        b = "[" * n * "]"
        width(b) > nw && (b = first(b, nw - 2) * "…]")
        room = max(cols - 4 - nw - 2 - 4 - 2 - 2, 16)
        ps = isempty(string(d)) ? [""] : wrapcell(string(d), room)
        println("    ", pad(b, nw), "  ", ok ? sty("PASS", :green) : sty("FAIL", :red), "  ", ps[1])
        foreach(x -> println(" "^(4 + nw + 2 + 4 + 2), sty(x, :dim)), ps[2:end])
    end
    for h in heads
        ps = wrapcell(h, cols - 6)
        println("    ", sty("→ ", :dim), verdict(ps[1]))
        foreach(x -> println("      ", verdict(x)), ps[2:end])
    end
end

# What a running script has done so far, read from its log: checks passed,
# gates passed, records checks reported ok. Only what it has printed.
function live_detail(logf)
    isfile(logf) || return ""
    t = replace(read(logf, String), r"\e\[[0-9;]*m" => "")
    k = count(r"PASS = true", t) + count(r"(?m)^[A-Za-z][A-Za-z0-9_]*\s{2,}PASS\s", t)
    k > 0 && return "$k checks passed so far"
    k = count(r"(?m)\s+ok$", t)
    k > 0 && return "$k checks ok so far"
    return ""
end

# While a script runs: which task of how many, a block sweeping back and forth
# (the process is alive), the time elapsed, and what its log says it has done.
# Only on an interactive terminal; nothing here is predicted.
const STEP = Ref(0); const STEPS = Ref(0)
function await(p, label, logf)
    if !COLOR
        wait(p); return p
    end
    spin = collect("⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏"); w = 20; i = 0; t0 = time(); det = ""
    while process_running(p)
        el = time() - t0
        span = w - 5; q = i % (2span); q >= span && (q = 2span - q)
        bar = "░"^q * "█"^5 * "░"^(w - 5 - q)
        i % 8 == 0 && (det = live_detail(logf))
        print("\r  ", sty(spin[i % 10 + 1], :cyan), " ", sty("[$(STEP[])/$(STEPS[])]", :dim), " ",
              rpad(label, 14), " ", sty(bar, :cyan), @sprintf(" %4ds  ", el), sty(det, :dim), "\e[K")
        i += 1; sleep(0.12)
    end
    print("\r\e[K"); wait(p); return p
end

function run!(task, cmd, ok_pattern; dir = ROOT, verbose = false, show = "",
              key = replace(first(split(task)), r"[^A-Za-z0-9]" => ""))
    STEP[] += 1
    section("[$(STEP[])/$(STEPS[])] " * uppercase(task))
    println("  ", sty("\$ " * (isempty(show) ? join(cmd.exec, " ") : show), :dim))
    mkpath(joinpath(ROOT, "logs", "ui"))
    logf = joinpath(ROOT, "logs", "ui", key * ".log")
    t0 = time()
    env = merge(ENV, Dict("CHIQUI_NO_RECORD" => "1"))
    okrun = open(logf, "w") do io
        c = setenv(Cmd(cmd; dir = dir), env)
        verbose ? success(pipeline(c; stdout = stdout, stderr = stderr)) :
                  success(await(run(pipeline(c; stdout = io, stderr = io); wait = false), replace(key, "_" => " "), logf))
    end
    dt = time() - t0
    out = isfile(logf) ? read(logf, String) : ""
    good = okrun && (verbose || ok_pattern === nothing || occursin(ok_pattern, out))
    v = good ? "PASS" : "FAIL"
    rel = relpath(logf, ROOT)
    println("  ", pad("[" * replace(key, "_" => " ") * "]", 36), " ", verdict(v), "  ", sty(@sprintf("%.0f s", dt), :dim))
    println("    ", sty("log: " * rel, :dim))
    if !verbose
        rows, heads = condensed(out)
        isempty(rows) && isempty(heads) || print_checks(rows, heads)
    end
    push!(RESULTS, (replace(key, "_" => " "), v, dt, rel))
    return good
end

julia(args...) = `$(Base.julia_cmd()) --project=$ROOT $args`

tasks = Dict{String,Function}(
    "verify"  => v -> run!("verify · the A₁₆ certificate", julia("pipeline/certify_a16.jl"),
                           r"FINAL FIRST-ORDER CERTIFICATE: CERTIFIED"; verbose = v,
                           show = "julia --project=. pipeline/certify_a16.jl"),
    "radius"  => v -> run!("radius · Theorem 6.4", julia("pipeline/certify_radius.jl"),
                           r"CERTIFIED r >="; verbose = v,
                           show = "julia --project=. pipeline/certify_radius.jl"),
    "family"  => v -> all(n -> run!("family · A$n", julia("pipeline/certify_family.jl", string(n)),
                                    Regex("FAMILY CERTIFICATE A$n: CERTIFIED"); verbose = v,
                                    show = "julia --project=. pipeline/certify_family.jl $n", key = "family_A$n"), (32, 64)),
    "z"       => v -> all(n -> run!("z · Z$n", julia("pipeline/certify_z.jl", string(n)),
                                    Regex("FAMILY CERTIFICATE Z$n: CERTIFIED"); verbose = v,
                                    show = "julia --project=. pipeline/certify_z.jl $n", key = "z_Z$n"), (32, 64)),
    "independent" => v -> run!("independent · a second implementation, in Python", `python3 pipeline/independent/verify.py`,
                           r"INDEPENDENT CROSS-CHECK: PASSED"; verbose = v,
                           show = "python3 pipeline/independent/verify.py", key = "independent"),
    "test"    => v -> run!("test · the Julia suite", julia("test/runtests.jl"), nothing; verbose = v,
                           show = "julia --project=. test/runtests.jl"),
    "records" => v -> run!("records · against the tree and the Lean layer", julia("pipeline/check_records.jl"),
                           r"RECORDS CHECK PASS"; verbose = v,
                           show = "julia --project=. pipeline/check_records.jl"),
    "lean"    => v -> begin
        if Sys.which("lake") === nothing || !isdir(joinpath(ROOT, "lean", ".lake"))
            section("LEAN"); note("skipped: lake or the Mathlib cache is missing (make lean-cache)")
            push!(RESULTS, ("lean", "SKIPPED", 0.0, "—")); true
        else
            run!("lean · the A₁₆ formal layer", `bash ./verify.sh`, r"LEAN CERTIFICATE PASS";
                 dir = joinpath(ROOT, "lean"), verbose = v, show = "cd lean && ./verify.sh")
        end
    end,
)

function summary()
    isempty(RESULTS) && return
    section("SUMMARY")
    table(["task", "result", "time", "full output"],
          [[t, verdict(v), @sprintf("%.0f s", s), l] for (t, v, s, l) in RESULTS]; right = [3])
    allok = all(r -> r[2] in ("PASS", "SKIPPED"), RESULTS)
    println("\n  ", allok ? sty("All requested checks passed.", :green, :bold) :
                            sty("Some checks failed; see the full output above.", :red, :bold))
end

function help()
    section("USAGE · julia --project=. chiquipoli.jl [task] [--verbose]")
    table(["task", "what it does"], [
        ["status", "what is certified, read from results/ (the default; no computation)"],
        ["verify", "re-run the A₁₆ certificate (Theorem 6.3)"],
        ["radius", "re-run the explicit radius (Theorem 6.4)"],
        ["family", "re-run A₃₂ and A₆₄ (Theorem 6.6)"],
        ["z", "re-run Z₃₂ and Z₆₄ (Theorem 6.8)"],
        ["independent", "re-check A₁₆, A₃₂, A₆₄, Z₃₂, Z₆₄ with a second implementation (Python, no Julia)"],
        ["test", "the Julia test suite"],
        ["records", "every record against the tree and the Lean layer"],
        ["lean", "the A₁₆ Lean layer (needs lake and the Mathlib cache)"],
        ["all", "test, verify, radius, family, z, independent, records"]])
    note("--verbose streams each script's own output. Nothing here writes a record.")
end

function main(args)
    verbose = "--verbose" in args
    names = filter(a -> !startswith(a, "--"), args)
    task = isempty(names) ? "status" : names[1]
    banner()
    if task in ("help", "-h")
        help(); return 0
    elseif task == "status"
        status(); return 0
    elseif task == "all"
        STEPS[] = 9                       # test, verify, radius, family A32 and A64, z Z32 and Z64, independent, records
        ok = true
        for t in ("test", "verify", "radius", "family", "z", "independent", "records")
            ok &= tasks[t](verbose)
        end
        summary(); return ok ? 0 : 1
    elseif haskey(tasks, task)
        STEPS[] = task in ("family", "z") ? 2 : 1
        ok = tasks[task](verbose); summary(); return ok ? 0 : 1
    else
        println("\n  unknown task '$task'"); help(); return 2
    end
end

exit(main(ARGS))
